# ==============================================================================# 030_PLUGIN_ENGINE.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS plugins(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    name TEXT,    version TEXT,    author TEXT,    status TEXT)""")conn.commit()PLUGINS = [("BOOT","1.0.0","IOTEC","ONLINE"),("KERNEL","1.0.0","IOTEC","ONLINE"),("EVENT_ENGINE","1.0.0","IOTEC","ONLINE"),("MISSION_ENGINE","1.0.0","IOTEC","ONLINE"),("API_CORE","1.0.0","IOTEC","ONLINE"),("API_SERVER","1.0.0","IOTEC","ONLINE"),("SECURITY_ENGINE","1.0.0","IOTEC","ONLINE"),("AUTH_ENGINE","1.0.0","IOTEC","ONLINE"),("SESSION_ENGINE","1.0.0","IOTEC","ONLINE"),("AUDIT_ENGINE","1.0.0","IOTEC","ONLINE"),("NOTIFICATION_ENGINE","1.0.0","IOTEC","ONLINE"),("SETTINGS_ENGINE","1.0.0","IOTEC","ONLINE")]for name,version,author,status in PLUGINS:    cur.execute(        "SELECT id FROM plugins WHERE name=?",        (name,)    )    if cur.fetchone() is None:        cur.execute("""        INSERT INTO plugins(            created_at,            name,            version,            author,            status        )        VALUES(?,?,?,?,?)        """,(            datetime.now().isoformat(),            name,            version,            author,            status        ))conn.commit()cur.execute("""SELECTid,name,version,statusFROM pluginsORDER BY id""")print("="*80)print("PLUGIN ENGINE")print("="*80)for row in cur.fetchall():    print(        f"{row['id']:03d} "        f"{row['name']:<24}"        f"{row['version']:<8}"        f"{row['status']}"    )print("="*80)conn.close()

